head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;

//////////////////////////////////////
scwin.key_row = '';
scwin.isur_id = '';
scwin.corp_usr_tp_cd = '';
scwin.contn_id = '';
scwin.contn_grp_id = '';
scwin.ans_obj_contn_id = '';
scwin.contn_depth = '';
scwin.noti_obj_sys_tp_cd = '';
scwin.ques_bz_tp_cd = '';
scwin.questr_nm = '';
scwin.opn_yn = '';
scwin.mode = frame.opener.scwin.mode; //ex) I 인서트, U 업데이트
//////////////////////////////////////

scwin.vScrenID = "ULDSTF30342.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    if (scwin.mode == 'I') {
        scwin.key_row = frame.opener.scwin.key_row;
        scwin.isur_id = frame.opener.scwin.isur_id;
        scwin.corp_usr_tp_cd = frame.opener.scwin.corp_usr_tp_cd;
        scwin.contn_id = frame.opener.scwin.contn_id;
        scwin.contn_grp_id = frame.opener.scwin.contn_grp_id;
        scwin.ans_obj_contn_id = frame.opener.scwin.ans_obj_contn_id;
        scwin.noti_obj_sys_tp_cd = frame.opener.scwin.noti_obj_sys_tp_cd;
        scwin.ques_bz_tp_cd = frame.opener.scwin.ques_bz_tp_cd;
        scwin.opn_yn = frame.opener.scwin.opn_yn;
        $c.stf.showObj(btn_Delete, false);
        $c.stf.setObjectValue(txb_ISUR_CD, scwin.isur_id);
        $c.stf.setObjectValue(txb_CORP_USR_TP_CD, scwin.corp_usr_tp_cd);
        $c.stf.setObjectValue(txb_CONTN_ID, scwin.contn_id);
        $c.stf.setObjectValue(txb_CONTN_GRP_ID, scwin.contn_grp_id);
        $c.stf.setObjectValue(txb_ANS_OBJ_CONTN_ID, scwin.ans_obj_contn_id);
        $c.stf.setObjectValue(txb_NOTI_OBJ_SYS_TP_CD, scwin.noti_obj_sys_tp_cd);
        $c.stf.setObjectValue(txb_QUES_BZ_TP_CD, scwin.ques_bz_tp_cd);
        $c.stf.setObjectValue(txb_QUESTR_NM, js_emp_nm);
        $c.stf.setObjectValue(txb_OPN_YN, scwin.opn_yn);
    } else {
        scwin.key_row = frame.opener.scwin.key_row;
        scwin.contn_id = frame.opener.dts_qnaList.getCellData(scwin.key_row, "CONTN_ID");
        scwin.contn_grp_id = frame.opener.dts_qnaList.getCellData(scwin.key_row, "CONTN_GRP_ID");
        scwin.ans_obj_contn_id = frame.opener.dts_qnaList.getCellData(scwin.key_row, "ANS_OBJ_CONTN_ID");
        scwin.noti_obj_sys_tp_cd = frame.opener.dts_qnaList.getCellData(scwin.key_row, "NOTI_OBJ_SYS_TP_CD");
    }
    //alert("contn_id : " + contn_id + " : contn_grp_id : " + contn_grp_id + " : ans_obj_contn_id : " + ans_obj_contn_id + " : contn_depth : " + contn_depth + " : intl_acntg_bas_bbs_tp_cd : " + intl_acntg_bas_bbs_tp_cd);

};
scwin.initPage = function() {
    if (scwin.mode == 'I') {
        //미답변상태
        scwin.fn_SetNewMode();
    } else {
        //답변상태

    }

    //*
    $c.stf.showObj(panel_Hidden, false);
    //*/

};
scwin.readmode = function() {
    //색상변화와 리드온리

};
scwin.fn_SetNewMode = function() {
    dts_MASTER.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=VOC_QNA_INOUT";
    dts_MASTER.Reset();
    dts_MASTER.insertRow();
    scwin.fn_SetCode();
};
scwin.fn_search = function() {
    var url = "/VocQnA.do?method=readVocQnA";
    url += "&CONTN_ID=" + scwin.contn_id;
    url += "&CONTN_GRP_ID=" + scwin.contn_grp_id;
    url += "&ANS_OBJ_CONTN_ID=" + scwin.ans_obj_contn_id;
    url += "&NOTI_OBJ_SYS_TP_CD=" + scwin.noti_obj_sys_tp_cd;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //alert(url);
    dts_MASTER.DataID = encodeURI(url);
    dts_MASTER.Reset();
};
scwin.fn_Save = function() {
    if ($c.stf.getObjectValue(txb_QUES_TITLE) == '') {
        $c.win.alert("제목을 입력해주세요.");
        txb_QUES_TITLE.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txa_QUES_CONTN) == '') {
        $c.win.alert("내용을 입력해주세요.");
        txa_QUES_CONTN.focus();
        return false;
    }
    $c.stf.setObjectValue(txb_QUESTR_ID, scwin.gEmpNo);
    $c.stf.setObjectValue(txb_QUES_ANS_TP_CD, '2'); //2:답변

    if (scwin.mode == 'I') {
        scwin.fn_Insert();
    } else {
        scwin.fn_Update();
    }
};
scwin.fn_Insert = function() {
    var res = window.confirm("[저장]하시겠습니까?");
    if (res) {
        gLastJob = "저장";
        var url = "/VocQnA.do?method=insertVocQnA" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        //alert(dts_MASTER.Text);

        ///*
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_MASTER)";
        trs_Save.post();
        //*/

    }
};
scwin.fn_Update = function() {
    var res = window.confirm("[수정]하시겠습니까?");
    if (res) {
        gLastJob = "수정";
        var url = "/VocQnA.do?method=updateVocQnA" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        //alert(dts_MASTER.Text);

        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_MASTER)";
        trs_Save.post();
    }
};
scwin.fn_Delete = function() {
    var res = window.confirm("[삭제]하시겠습니까?");
    if (res) {
        dts_MASTER.setCellData(1, "DEL_YN", 'Y');
        gLastJob = "삭제";
        var url = "/VocQnA.do?method=deleteVocQnA" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        //alert(dts_MASTER.Text);
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_MASTER)";
        trs_Save.post();
    }
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.btn_Delete_onclick = function() {
    scwin.fn_Delete();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    var msg = $c.stf.getMessageParam("MSG-A001", gLastJob);
    $c.win.alert(msg);

    ////////////////
    if (scwin.mode == 'I') {
        var fr_fn_Search = $c.frame.path("../../").fn_search;
        frame.opener.close();
        await $c.frame.CloseFrame();
        fr_fn_Search();
    } else {
        var fr_fn_Search = $c.frame.path("../").fn_search;
        fr_fn_Search();
        await $c.frame.CloseFrame();
    }
};
scwin.grd_FILE_LIST_OnClick = function(row, colid) {
    fn_DownLoad(row, colid);
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    scwin.initPage();
    if (scwin.mode != 'I') {
        scwin.fn_search();
    }
};
